1	# BuildMatrix.Tests.ps1
2	#
3	# Pester 5 tests for the build-matrix generator.
4	#
5	# These tests were written test-first (red/green TDD). Each Describe block
6	# corresponds to a unit of functionality that was implemented only after the
7	# test for it failed for the right reason.
8	#
9	# Run with:  Invoke-Pester -Path ./BuildMatrix.Tests.ps1
10	
11	BeforeAll {
12	    # Import the module under test. $PSScriptRoot is the directory of this file.
13	    $script:ModulePath = Join-Path $PSScriptRoot 'BuildMatrix.psm1'
14	    Import-Module $script:ModulePath -Force
15	}
16	
17	Describe 'Expand-MatrixAxes (cartesian product)' {
18	
19	    It 'expands a single axis into one combination per value' {
20	        $axes = [ordered]@{ os = @('ubuntu-latest', 'windows-latest') }
21	        $result = Expand-MatrixAxes -Axes $axes
22	
23	        $result.Count | Should -Be 2
24	        $result[0].os | Should -Be 'ubuntu-latest'
25	        $result[1].os | Should -Be 'windows-latest'
26	    }
27	
28	    It 'produces the cartesian product of two axes in odometer order (first axis slowest)' {
29	        $axes = [ordered]@{
30	            os   = @('ubuntu-latest', 'windows-latest')
31	            node = @('18', '20')
32	        }
33	        $result = Expand-MatrixAxes -Axes $axes
34	
35	        $result.Count | Should -Be 4
36	        # First axis varies slowest, last axis varies fastest.
37	        ($result | ForEach-Object { "$($_.os)/$($_.node)" }) | Should -Be @(
38	            'ubuntu-latest/18',
39	            'ubuntu-latest/20',
40	            'windows-latest/18',
41	            'windows-latest/20'
42	        )
43	    }
44	
45	    It 'preserves boolean feature-flag values as real booleans' {
46	        $axes = [ordered]@{
47	            os           = @('ubuntu-latest')
48	            experimental = @($true, $false)
49	        }
50	        $result = Expand-MatrixAxes -Axes $axes
51	
52	        $result.Count | Should -Be 2
53	        $result[0].experimental | Should -BeOfType [bool]
54	        $result[0].experimental | Should -BeTrue
55	        $result[1].experimental | Should -BeFalse
56	    }
57	
58	    It 'returns an empty list when there are no axes' {
59	        $result = Expand-MatrixAxes -Axes ([ordered]@{})
60	        @($result).Count | Should -Be 0
61	    }
62	}
