64	Describe 'Remove-ExcludedCombinations (exclude rules)' {
65	
66	    BeforeEach {
67	        $script:combos = Expand-MatrixAxes -Axes ([ordered]@{
68	            os   = @('ubuntu-latest', 'windows-latest')
69	            node = @('18', '20')
70	        })
71	    }
72	
73	    It 'removes combinations that match an exclude rule on every key' {
74	        $exclude = @(
75	            [ordered]@{ os = 'windows-latest'; node = '18' }
76	        )
77	        $result = Remove-ExcludedCombinations -Combinations $script:combos -Exclude $exclude
78	
79	        @($result).Count | Should -Be 3
80	        ($result | Where-Object { $_.os -eq 'windows-latest' -and $_.node -eq '18' }) | Should -BeNullOrEmpty
81	    }
82	
83	    It 'treats an exclude rule as a partial match (removes all combos matching the given keys)' {
84	        $exclude = @(
85	            [ordered]@{ os = 'windows-latest' }
86	        )
87	        $result = Remove-ExcludedCombinations -Combinations $script:combos -Exclude $exclude
88	
89	        @($result).Count | Should -Be 2
90	        ($result | ForEach-Object { $_.os } | Sort-Object -Unique) | Should -Be 'ubuntu-latest'
91	    }
92	
93	    It 'returns combinations unchanged when there are no exclude rules' {
94	        $result = Remove-ExcludedCombinations -Combinations $script:combos -Exclude @()
95	        @($result).Count | Should -Be 4
96	    }
97	
98	    It 'matches boolean values correctly when excluding' {
99	        $combos = Expand-MatrixAxes -Axes ([ordered]@{
100	            os           = @('ubuntu-latest', 'windows-latest')
101	            experimental = @($true, $false)
102	        })
103	        $exclude = @(
104	            [ordered]@{ os = 'windows-latest'; experimental = $true }
105	        )
106	        $result = Remove-ExcludedCombinations -Combinations $combos -Exclude $exclude
107	
108	        @($result).Count | Should -Be 3
109	        ($result | Where-Object { $_.os -eq 'windows-latest' -and $_.experimental -eq $true }) | Should -BeNullOrEmpty
110	    }
111	}
