113	Describe 'Add-IncludedCombinations (include rules)' {
114	
115	    It 'adds a new key to every combination when the include has no axis keys' {
116	        $combos = Expand-MatrixAxes -Axes ([ordered]@{ os = @('ubuntu-latest', 'windows-latest') })
117	        $axisNames = @('os')
118	        $include = @( [ordered]@{ color = 'green' } )
