154	    It 'reproduces the canonical GitHub Actions fruit/animal include example exactly' {
155	        # https://docs.github.com/actions - the documented include semantics.
156	        $combos = Expand-MatrixAxes -Axes ([ordered]@{
157	            fruit  = @('apple', 'pear')
158	            animal = @('cat', 'dog')
159	        })
160	        $include = @(
161	            [ordered]@{ color = 'green' }
162	            [ordered]@{ color = 'pink'; animal = 'cat' }
163	            [ordered]@{ fruit = 'apple'; shape = 'circle' }
164	            [ordered]@{ fruit = 'banana' }
165	            [ordered]@{ fruit = 'banana'; animal = 'cat' }
166	        )
167	
168	        $result = Add-IncludedCombinations -Combinations $combos -Include $include -AxisNames @('fruit', 'animal')
169	
170	        # Serialize each combo to a stable string for comparison.
171	        $asString = $result | ForEach-Object {
172	            $combo = $_
173	            $pairs = foreach ($k in $combo.Keys) { "$k=$($combo[$k])" }
174	            $pairs -join ','
175	        }
176	
177	        $expected = @(
178	            'fruit=apple,animal=cat,color=pink,shape=circle'
179	            'fruit=apple,animal=dog,color=green,shape=circle'
180	            'fruit=pear,animal=cat,color=pink'
181	            'fruit=pear,animal=dog,color=green'
182	            'fruit=banana'
183	            'fruit=banana,animal=cat'
184	        )
185	        $asString | Should -Be $expected
186	    }
187	
188	    It 'returns combinations unchanged when there are no include rules' {
189	        $combos = Expand-MatrixAxes -Axes ([ordered]@{ os = @('ubuntu-latest') })
190	        $result = Add-IncludedCombinations -Combinations $combos -Include @() -AxisNames @('os')
191	        @($result).Count | Should -Be 1
192	    }
193	}
