195	Describe 'Assert-MatrixSize (size validation)' {
196	
197	    It 'does not throw when the matrix is within the limit' {
198	        $combos = @([ordered]@{ a = 1 }, [ordered]@{ a = 2 })
199	        { Assert-MatrixSize -Combinations $combos -MaxSize 5 } | Should -Not -Throw
