223	Describe 'New-BuildMatrix (orchestration)' {
224	
225	    It 'builds a strategy object from a simple OS x version config' {
226	        $config = @{
227	            matrix = [ordered]@{
228	                os   = @('ubuntu-latest', 'windows-latest')
229	                node = @('18', '20')
230	            }
231	        }
232	        $strategy = New-BuildMatrix -Config $config
233	
234	        $strategy.matrix.include.Count | Should -Be 4
235	        $strategy.'fail-fast' | Should -BeTrue   # GitHub default
236	        $strategy.Contains('max-parallel') | Should -BeFalse
237	    }
238	
239	    It 'applies exclude then include rules and feature flags together' {
240	        $config = @{
241	            matrix = [ordered]@{
242	                os           = @('ubuntu-latest', 'windows-latest')
243	                node         = @('18', '20')
244	                experimental = @($false)
245	                exclude      = @( [ordered]@{ os = 'windows-latest'; node = '18' } )
246	                include      = @( [ordered]@{ os = 'ubuntu-latest'; node = '20'; coverage = $true } )
247	            }
248	        }
249	        $strategy = New-BuildMatrix -Config $config
250	
